/**
 * Payment Webhook Handler — Processes payment gateway callbacks.
 * Verifies signatures, updates order/payment status.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const crypto = require('crypto');
const { env } = require('../config/env');
const paymentService = require('../services/payment.service');

/**
 * Stripe Webhook — POST /api/webhooks/stripe
 * Raw body is required for signature verification.
 */
router.post('/stripe', async (req, res) => {
  const sig = req.headers['stripe-signature'];
  const { stripe } = require('../config/payment');

  try {
    const event = stripe.webhooks.constructEvent(
      req.body, // Raw body (set up in app.js)
      sig,
      env.STRIPE_WEBHOOK_SECRET
    );

    // Handle the event
    switch (event.type) {
      case 'checkout.session.completed': {
        const session = event.data.object;
        const orderId = session.metadata?.orderId;
        if (orderId) {
          await paymentService.handlePaymentSuccess(orderId, session.payment_intent, 'stripe');
          console.log(`✅ [Stripe] Payment successful for order: ${orderId}`);
        }
        break;
      }

      case 'payment_intent.payment_failed': {
        const intent = event.data.object;
        const orderId = intent.metadata?.orderId;
        if (orderId) {
          await paymentService.handlePaymentFailure(orderId, 'stripe', intent.last_payment_error?.message);
          console.log(`❌ [Stripe] Payment failed for order: ${orderId}`);
        }
        break;
      }

      default:
        console.log(`[Stripe] Unhandled event type: ${event.type}`);
    }

    res.json({ received: true });
  } catch (err) {
    console.error(`[Stripe] Webhook error: ${err.message}`);
    res.status(400).json({ error: `Webhook Error: ${err.message}` });
  }
});


module.exports = router;
